function showToast(message){toast.textContent=message;toast.classList.add("show");setTimeout(()=>toast.classList.remove("show"),2800)}
function renderProducts(){
 const list=searchProducts(marketplaceProducts,marketplaceFilters);
 grid.innerHTML=(list.length?list:[]).map(p=>`<article class="product marketplace-product" data-product-id="${escapeAttr(p.id||"")}"><div class="product-visual"><span class="product-symbol">${escapeHtml((p.category||"B").slice(0,1).toUpperCase())}</span></div><div class="product-body"><div class="product-meta"><span class="category-tag">${escapeHtml(p.category||"General")}</span><span class="stock ${escapeAttr(p.stockStatus||"")}">${escapeHtml(stockLabel(p.stockStatus))}</span></div><h3>${escapeHtml(p.name||"Unnamed product")}</h3><p class="product-description">${escapeHtml(p.description||"Supplier details available after enquiry.")}</p><div class="price">${escapeHtml(productPrice(p))}</div><small class="supplier-line">${escapeHtml(p.supplierName||"BUILDIVA supplier network")}</small><button data-product="${escapeAttr(p.id||p.name||"")}">View / Request</button></div></article>`).join("") || `<div class="empty-state marketplace-empty"><strong>No matching products.</strong><span>Try another search or remove a filter.</span></div>`;
 bindProductButtons();
 const count=document.getElementById("marketplaceCount"); if(count) count.textContent=`${list.length} product${list.length===1?"":"s"}`;
 const source=document.getElementById("marketplaceSource"); if(source) source.textContent=window.__marketplaceSource==="live"?"Live supplier catalogue":"Catalogue preview";
}
function bindProductButtons(){document.querySelectorAll("[data-product]").forEach(btn=>btn.onclick=()=>openProduct(btn.dataset.product));}
function openProduct(id){
 const p=marketplaceProducts.find(x=>x.id===id||x.name===id); if(!p) return;
 let modal=document.getElementById("productModal"); if(!modal){modal=document.createElement("div");modal.id="productModal";modal.className="modal-backdrop";modal.hidden=true;modal.innerHTML=`<div class="account-modal product-modal" role="dialog" aria-modal="true"><button class="modal-close" id="closeProduct" aria-label="Close">×</button><div id="productPanel"></div></div>`;document.body.appendChild(modal);document.getElementById("closeProduct").onclick=()=>modal.hidden=true;}
 document.getElementById("productPanel").innerHTML=`<p class="eyebrow">${escapeHtml(p.category||"PRODUCT")}</p><h2>${escapeHtml(p.name||"Product")}</h2><p class="muted">${escapeHtml(p.description||"")}</p><div class="product-detail-grid"><div class="detail-box"><strong>Price</strong><span>${escapeHtml(productPrice(p))}</span></div><div class="detail-box"><strong>Unit</strong><span>${escapeHtml(p.unit||"On request")}</span></div><div class="detail-box"><strong>Availability</strong><span>${escapeHtml(stockLabel(p.stockStatus))}</span></div><div class="detail-box"><strong>Supplier</strong><span>${escapeHtml(p.supplierName||"BUILDIVA supplier network")}</span></div></div><div class="product-request"><h3>Need this product?</h3><p class="muted">Sign in to save the request to your BUILDIVA account, or create an account to start an enquiry.</p><button class="btn btn-primary" id="requestProduct">Request quotation</button></div>`;
 modal.hidden=false;document.getElementById("requestProduct").onclick=()=>{modal.hidden=true; if(auth.currentUser){openRFQModal(p);}else openAuth("signup");};
}
async function initMarketplace(){
 const result=await loadMarketplaceProducts(); marketplaceProducts=result.products; window.__marketplaceSource=result.source; renderProducts();
 document.querySelectorAll("[data-category]").forEach(b=>b.onclick=()=>{marketplaceFilters.category=b.dataset.category;document.getElementById("marketplaceFilters")?.scrollIntoView({behavior:"smooth",block:"center"});renderProducts();});
 const hero=document.getElementById("heroSearch"), heroBtn=document.getElementById("heroSearchBtn");
 const doSearch=()=>{marketplaceFilters.queryText=hero?.value||"";document.getElementById("products")?.scrollIntoView({behavior:"smooth"});renderProducts();};
 heroBtn?.addEventListener("click",doSearch); hero?.addEventListener("keydown",e=>{if(e.key==="Enter")doSearch();});
 document.getElementById("marketplaceSearch")?.addEventListener("input",e=>{marketplaceFilters.queryText=e.target.value;renderProducts();});
 document.getElementById("marketplaceCategory")?.addEventListener("change",e=>{marketplaceFilters.category=e.target.value;renderProducts();});
 document.getElementById("marketplaceStock")?.addEventListener("change",e=>{marketplaceFilters.stock=e.target.value;renderProducts();});
 document.getElementById("clearMarketplaceFilters")?.addEventListener("click",()=>{marketplaceFilters={queryText:"",category:"",stock:"",minPrice:"",maxPrice:""};["marketplaceSearch","marketplaceCategory","marketplaceStock"].forEach(id=>{const el=document.getElementById(id);if(el)el.value=""});if(hero)hero.value="";renderProducts();});
}



let currentRFQContext=null;
function ensureRFQModal(){
 if(document.getElementById("rfqModal")) return;
 const el=document.getElementById("rfqModal");
 document.getElementById("closeRFQ").onclick=()=>el.hidden=true;
 el.addEventListener("click",e=>{if(e.target===el)el.hidden=true});
}
function openRFQModal(product=null){
 ensureRFQModal(); const modal=document.getElementById("rfqModal"), panel=document.getElementById("rfqPanel");
 if(!auth.currentUser){modal.hidden=true;openAuth("signup");return;}
 currentRFQContext=product;
 const itemName=product?.name||"";
 panel.innerHTML=`<div><p class="eyebrow">PROCUREMENT REQUEST</p><h2 id="rfqTitle">Create an RFQ</h2><p class="muted">Describe what you need. Supplier matching is initially based on approved supplier categories and coverage; no supplier is presented as verified unless the platform has verified them.</p><form id="rfqForm"><div class="rfq-form-grid"><label>Request title<input name="title" required value="${escapeAttr(product?`Supply of ${product.name}`:"")}" placeholder="e.g. Cement for building project"></label><label>Category<select name="category" required><option>Cement</option><option>Blocks</option><option>Iron Rods</option><option>Roofing</option><option>Plumbing</option><option>Electrical</option><option>Construction Services</option><option>Technology & IT</option><option>Office & General Supplies</option><option>Logistics</option><option>Other Materials</option></select></label><label class="full">Delivery location<input name="deliveryLocation" required placeholder="City / state / project site"></label><label>Needed by<input name="neededBy" type="date"></label><label>Notes<textarea name="notes" rows="2" placeholder="Specifications, brand preference, delivery instructions…"></textarea></label><div class="full"><div class="rfq-card-head"><strong>Requested items</strong><button type="button" class="btn btn-ghost" id="addRFQLine">+ Add item</button></div><div class="rfq-lines" id="rfqLines"></div></div></div><p id="rfqMessage" class="form-message"></p><button class="btn btn-primary" type="submit">Send RFQ to matching suppliers</button></form></div>`;
 const lines=document.getElementById("rfqLines");
 function addLine(item={}){const row=document.createElement("div");row.className="rfq-line";row.innerHTML=`<input name="itemName" required placeholder="Product or service" value="${escapeAttr(item.name||"")}"><input name="quantity" type="number" min="0.01" step="0.01" required placeholder="Qty" value="${item.quantity||1}"><input name="unit" required placeholder="Unit" value="${escapeAttr(item.unit||product?.unit||"unit")}"><button type="button" class="btn btn-ghost remove-line">Remove</button>`;row.querySelector(".remove-line").onclick=()=>{if(lines.children.length>1)row.remove();};lines.appendChild(row);}
 addLine(product?{name:product.name,unit:product.unit}:{}); document.getElementById("addRFQLine").onclick=()=>addLine();
 document.getElementById("rfqForm").onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,fd=new FormData(f),m=document.getElementById("rfqMessage");m.textContent="Sending RFQ…";const rows=[...document.querySelectorAll("#rfqLines .rfq-line")];const items=rows.map(r=>({name:r.querySelector('[name=itemName]').value,quantity:r.querySelector('[name=quantity]').value,unit:r.querySelector('[name=unit]').value,productId:product?.id||""}));try{const id=await createRFQ({user:auth.currentUser,title:fd.get("title"),category:fd.get("category"),items,deliveryLocation:fd.get("deliveryLocation"),neededBy:fd.get("neededBy"),notes:fd.get("notes")});modal.hidden=true;showToast(`RFQ ${id.slice(0,8)} created.`);renderRFQDashboard();}catch(err){m.textContent=humanAuthError(err)}};
 modal.hidden=false;
}
function rfqStatus(status){return `<span class="status-pill ${escapeAttr(status||"")}">${escapeHtml(status||"open")}</span>`}
async function renderRFQDashboard(){
 const el=document.getElementById("rfqDashboard"); if(!el) return;
 const user=auth.currentUser; if(!user){el.innerHTML=`<div class="rfq-empty"><strong>Sign in to manage procurement requests.</strong><span>Your RFQs and supplier quotations will appear here.</span></div>`;return;}
 el.innerHTML=`<div class="account-loading">Loading procurement workspace…</div>`;
 try{const rfqs=await getCustomerRFQs(user.uid);if(!rfqs.length){el.innerHTML=`<div class="rfq-empty"><strong>No RFQs yet.</strong><span>Create your first procurement request and BUILDIVA can route it to matched suppliers.</span><br><button class="btn btn-primary" id="emptyCreateRFQ">Create RFQ</button></div>`;document.getElementById("emptyCreateRFQ").onclick=()=>openRFQModal();return;}
 el.innerHTML=rfqs.map(r=>`<article class="rfq-card"><div class="rfq-card-head"><div><h3>${escapeHtml(r.title||"Procurement request")}</h3><div class="rfq-meta"><span>${escapeHtml(r.category||"General")}</span><span>RFQ ${escapeHtml(r.id.slice(0,8))}</span><span>${r.neededBy?`Needed by ${escapeHtml(r.neededBy)}`:"Flexible timing"}</span></div></div>${rfqStatus(r.status)}</div><div class="rfq-items">${(r.items||[]).map(i=>`<span class="rfq-item-chip">${escapeHtml(i.name)} × ${escapeHtml(i.quantity)} ${escapeHtml(i.unit)}</span>`).join("")}</div><p class="muted">Delivery: ${escapeHtml(r.deliveryLocation||"Not specified")}</p><div class="rfq-actions"><button class="btn btn-ghost" data-view-quotes="${escapeAttr(r.id)}">Compare quotations</button></div><div class="quote-list" id="quotes-${escapeAttr(r.id)}"></div></article>`).join("");
 document.querySelectorAll("[data-view-quotes]").forEach(b=>b.onclick=()=>loadQuotesForRFQ(b.dataset.viewQuotes,user.uid));
 }catch(err){el.innerHTML=`<div class="rfq-empty"><strong>Procurement workspace unavailable.</strong><span>${escapeHtml(humanAuthError(err))}</span></div>`;}
}
async function loadQuotesForRFQ(rfqId,customerId){const box=document.getElementById(`quotes-${rfqId}`);if(!box)return;box.innerHTML=`<div class="account-loading">Loading quotations…</div>`;try{const quotes=await getRFQQuotes(rfqId,customerId);if(!quotes.length){box.innerHTML=`<div class="rfq-empty"><strong>No quotations yet.</strong><span>Matched suppliers can submit offers once the RFQ is available to them.</span></div>`;return;}box.innerHTML=quotes.map(q=>`<article class="quote-card"><div class="quote-head"><div><h4>Supplier quotation</h4><div class="quote-meta"><span>Supplier ID ${escapeHtml(q.supplierId.slice(0,8))}</span><span>${escapeHtml(q.leadTime||"Lead time on request")}</span></div></div><div>${rfqStatus(q.status)}<div class="quote-total">₦${Number(q.total||0).toLocaleString("en-NG")}</div></div></div><div class="quote-grid"><div><strong>Subtotal</strong><span>₦${Number(q.subtotal||0).toLocaleString("en-NG")}</span></div><div><strong>Delivery</strong><span>₦${Number(q.deliveryFee||0).toLocaleString("en-NG")}</span></div><div><strong>Valid until</strong><span>${escapeHtml(q.validUntil||"Not specified")}</span></div></div><div class="rfq-items">${(q.items||[]).map(i=>`<span class="rfq-item-chip">${escapeHtml(i.name)} × ${escapeHtml(i.quantity)} @ ₦${Number(i.unitPrice||0).toLocaleString("en-NG")}</span>`).join("")}</div><div class="rfq-actions">${q.status==="submitted"?`<button class="btn btn-primary" data-select-quote="${escapeAttr(q.id)}">Select quotation</button>`:""}</div></article>`).join("");document.querySelectorAll("[data-select-quote]").forEach(b=>b.onclick=async()=>{const quote=quotes.find(q=>q.id===b.dataset.selectQuote);if(!quote)return;if(!confirm("Select this quotation? The order will still require the next confirmation/payment workflow."))return;try{await selectQuotation({quote,customerId});const orderId=await prepareOrder({quote:{...quote,status:"selected"},customerId});showToast(`Quotation selected. Order ${orderId.slice(0,8)} prepared.`);loadQuotesForRFQ(rfqId,customerId);}catch(err){showToast(humanAuthError(err))}});}catch(err){box.innerHTML=`<div class="rfq-empty">${escapeHtml(humanAuthError(err))}</div>`}}
async function renderSupplierRFQs(){
 if(!auth.currentUser)return; const container=document.getElementById("supplierRFQList");if(!container)return;container.innerHTML=`<div class="account-loading">Loading matched RFQs…</div>`;try{const rfqs=await getSupplierRFQs(auth.currentUser.uid);if(!rfqs.length){container.innerHTML=`<div class="rfq-empty"><strong>No matched RFQ opportunities yet.</strong><span>Approved suppliers will see requests matched to their profile.</span></div>`;return;}container.innerHTML=rfqs.map(r=>`<article class="rfq-card supplier-opportunity"><div class="rfq-card-head"><div><h3>${escapeHtml(r.title||"RFQ")}</h3><div class="rfq-meta"><span>${escapeHtml(r.category||"General")}</span><span>${escapeHtml(r.deliveryLocation||"Location on request")}</span></div></div>${rfqStatus(r.status)}</div><div class="rfq-items">${(r.items||[]).map(i=>`<span class="rfq-item-chip">${escapeHtml(i.name)} × ${escapeHtml(i.quantity)} ${escapeHtml(i.unit)}</span>`).join("")}</div><button class="btn btn-primary" data-quote-rfq="${escapeAttr(r.id)}">Submit quotation</button></article>`).join("");document.querySelectorAll("[data-quote-rfq]").forEach(b=>b.onclick=()=>openQuoteModal(rfqs.find(r=>r.id===b.dataset.quoteRfq)));}catch(err){container.innerHTML=`<div class="rfq-empty">${escapeHtml(humanAuthError(err))}</div>`}
}
function openQuoteModal(rfq){if(!rfq)return;ensureRFQModal();const modal=document.getElementById("rfqModal"),panel=document.getElementById("rfqPanel");const rows=(rfq.items||[]).map(i=>`<div class="rfq-line quote-line"><input name="itemName" readonly value="${escapeAttr(i.name)}"><input name="quantity" readonly value="${escapeAttr(i.quantity)}"><input name="unitPrice" type="number" min="0" step="0.01" required placeholder="Unit price"></div>`).join("");panel.innerHTML=`<p class="eyebrow">SUPPLIER QUOTATION</p><h2>Quote: ${escapeHtml(rfq.title)}</h2><p class="muted">Enter your real offer. BUILDIVA should only show approved supplier opportunities that are actually matched to the request.</p><form id="quoteForm"><div class="rfq-lines">${rows}</div><div class="rfq-form-grid" style="margin-top:14px"><label>Delivery fee<input name="deliveryFee" type="number" min="0" step="0.01" value="0"></label><label>Lead time<input name="leadTime" required placeholder="e.g. 2–4 business days"></label><label>Valid until<input name="validUntil" type="date"></label><label>Notes<textarea name="notes" rows="2" placeholder="Terms, specifications, exclusions…"></textarea></label></div><p id="quoteMessage" class="form-message"></p><button class="btn btn-primary" type="submit">Submit quotation</button></form>`;document.getElementById("quoteForm").onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,fd=new FormData(f),m=document.getElementById("quoteMessage");const items=[...f.querySelectorAll(".quote-line")].map((row,i)=>({productId:rfq.items[i].productId||"",name:row.querySelector('[name=itemName]').value,quantity:row.querySelector('[name=quantity]').value,unit:rfq.items[i].unit,unitPrice:row.querySelector('[name=unitPrice]').value}));m.textContent="Submitting…";try{await submitQuotation({user:auth.currentUser,rfq,items,deliveryFee:fd.get("deliveryFee"),leadTime:fd.get("leadTime"),validUntil:fd.get("validUntil"),notes:fd.get("notes")});modal.hidden=true;showToast("Quotation submitted.");renderSupplierRFQs();}catch(err){m.textContent=humanAuthError(err)}};modal.hidden=false}

function ensureSupplierModal(){
 if(document.getElementById("supplierModal")) return;
 const el=document.createElement("div"); el.id="supplierModal"; el.className="modal-backdrop"; el.hidden=true;
 el.innerHTML=`<div class="supplier-modal" role="dialog" aria-modal="true" aria-labelledby="supplierTitle"><button class="modal-close" id="closeSupplier" aria-label="Close">×</button><div id="supplierPanel"></div></div>`;
 document.body.appendChild(el); document.getElementById("closeSupplier").onclick=()=>el.hidden=true;
}
async function renderSupplierFulfilment(){
 const box=document.getElementById("supplierFulfilmentList"); if(!box||!auth.currentUser)return; box.innerHTML=`<div class="account-loading">Loading fulfilment orders…</div>`;
 try{const orders=await getSupplierFulfilmentOrders(auth.currentUser.uid); const active=orders.filter(o=>!['awaiting_confirmation','awaiting_payment','cancelled','delivered'].includes(o.status)); if(!active.length){box.innerHTML=`<div class="empty-state">No fulfilment-ready orders yet.</div>`;return;} box.innerHTML=active.map(o=>`<article class="order-card fulfilment-card"><div class="order-head"><div><strong>Order ${escapeHtml(o.id.slice(0,8).toUpperCase())}</strong><span>${escapeHtml(orderStatusLabel(o.status))}</span></div><div class="order-total">${money(o.total)}</div></div><div class="order-summary"><span>Delivery: ${escapeHtml(orderStatusLabel(o.deliveryStatus||'pending'))}</span><span>Payment: ${escapeHtml(orderStatusLabel(o.paymentStatus||'unpaid'))}</span></div><div class="order-items">${(o.items||[]).map(i=>`<span>${escapeHtml(i.name||'Item')} × ${escapeHtml(i.quantity)} ${escapeHtml(i.unit||'unit')}</span>`).join('')}</div><div class="order-actions">${o.status==='confirmed'?`<button class="btn btn-primary" data-accept-order="${escapeAttr(o.id)}">Accept & start processing</button>`:''}${o.status==='processing'?`<button class="btn btn-primary" data-ready-order="${escapeAttr(o.id)}">Mark ready for dispatch</button>`:''}${o.status==='ready_for_dispatch'?`<button class="btn btn-primary" data-create-delivery="${escapeAttr(o.id)}">Create delivery record</button>`:''}${o.deliveryId?`<button class="btn btn-ghost" data-delivery-action="${escapeAttr(o.deliveryId)}" data-delivery-next="${o.deliveryStatus==='pending'?'':o.deliveryStatus==='assigned'?'picked_up':o.deliveryStatus==='picked_up'?'in_transit':o.deliveryStatus==='in_transit'?'out_for_delivery':o.deliveryStatus==='out_for_delivery'?'delivered':''}">Advance delivery</button><label class="pod-upload">Proof of delivery<input type="file" data-pod="${escapeAttr(o.deliveryId)}" accept=".pdf,.png,.jpg,.jpeg,.webp"></label>`:''}</div></article>`).join(''); box.querySelectorAll('[data-accept-order]').forEach(b=>b.onclick=async()=>{try{await acceptOrder(b.dataset.acceptOrder);showToast('Order accepted and processing started.');renderSupplierFulfilment()}catch(e){showToast(humanAuthError(e))}}); box.querySelectorAll('[data-ready-order]').forEach(b=>b.onclick=async()=>{try{await markOrderReady(b.dataset.readyOrder);showToast('Order marked ready for dispatch.');renderSupplierFulfilment()}catch(e){showToast(humanAuthError(e))}}); box.querySelectorAll('[data-create-delivery]').forEach(b=>b.onclick=async()=>{try{const r=await createDelivery(b.dataset.createDelivery);showToast(`Delivery ${r.trackingReference} created.`);renderSupplierFulfilment()}catch(e){showToast(humanAuthError(e))}}); box.querySelectorAll('[data-delivery-action]').forEach(b=>b.onclick=async()=>{if(!b.dataset.deliveryNext)return;try{await updateDeliveryStatus(b.dataset.deliveryAction,b.dataset.deliveryNext);showToast(`Delivery moved to ${b.dataset.deliveryNext.replaceAll('_',' ')}.`);renderSupplierFulfilment()}catch(e){showToast(humanAuthError(e))}}); box.querySelectorAll('[data-pod]').forEach(input=>input.onchange=async()=>{try{await uploadProofOfDelivery(input.dataset.pod,input.files?.[0]);showToast('Proof of delivery recorded.');renderSupplierFulfilment()}catch(e){showToast(humanAuthError(e))}}); }catch(e){box.innerHTML=`<div class="empty-state">${escapeHtml(humanAuthError(e))}</div>`}
}
