  document.getElementById("documentForm").onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,fd=new FormData(f),m=document.getElementById("documentMessage");m.textContent="Uploading…";try{const r=await uploadSupplierDocument(user.uid,fd.get("file"),fd.get("kind"));await saveSupplierProfile(user.uid,{lastUploadedDocument:r});m.textContent="Document uploaded for review."}catch(err){m.textContent=humanAuthError(err)}};
