async function renderSupplierPurchaseOrders(){
 const list=document.getElementById("supplierPOList"), detail=document.getElementById("supplierPOCollaboration"); if(!list||!detail||!auth.currentUser)return;
 list.innerHTML='<div class="account-loading">Loading purchase orders…</div>';
 try{
  const data=await getSupplierPurchaseOrders(50), orders=data.purchaseOrders||[];
  list.innerHTML=orders.length?orders.map(o=>`<article class="admin-row supplier-po-row"><div><strong>${escapeHtml(o.poNumber||o.id.slice(0,8).toUpperCase())}</strong><span>${escapeHtml(o.supplierName||"BUILDIVA purchase order")} · ${escapeHtml(String(o.status||"draft").replaceAll("_"," "))}</span><small>${escapeHtml(money(o.total||0))}${o.expectedDeliveryDate?` · Expected ${escapeHtml(o.expectedDeliveryDate)}`:""}${o.supplierExpectedDeliveryDate?` · Supplier date ${escapeHtml(o.supplierExpectedDeliveryDate)}`:""}</small></div><div class="admin-actions"><button class="btn btn-ghost" data-supplier-po-open="${escapeAttr(o.id)}">Open</button></div></article>`).join(""):`<div class="empty-state">No purchase orders have been assigned to this supplier.</div>`;
  list.querySelectorAll('[data-supplier-po-open]').forEach(b=>b.onclick=()=>openSupplierPurchaseOrder(b.dataset.supplierPoOpen,orders));
 }catch(e){list.innerHTML=`<div class="account-error">${escapeHtml(humanAuthError(e))}</div>`}
}
async function openSupplierPurchaseOrder(id, orders){
 const detail=document.getElementById("supplierPOCollaboration"), po=orders.find(x=>x.id===id); if(!detail||!po)return;
 detail.innerHTML='<div class="account-loading">Loading collaboration history…</div>';
 try{
  const c=await getPurchaseOrderCollaboration({purchaseOrderId:id});
  const ack=c.acknowledgements?.[0], conf=c.deliveryConfirmations?.[0];
  detail.innerHTML=`<div class="po-detail-head"><div><p class="eyebrow">PURCHASE ORDER</p><h4>${escapeHtml(po.poNumber||id.slice(0,8).toUpperCase())}</h4><p>${escapeHtml(String(po.status||"draft").replaceAll("_"," "))} · ${escapeHtml(money(po.total||0))}</p></div><span class="status-pill ${escapeAttr(po.status||"draft")}">${escapeHtml(po.status||"draft")}</span></div>
  <div class="po-items">${(po.items||[]).map(i=>`<div><strong>${escapeHtml(i.productName||i.name||"Item")}</strong><span>${escapeHtml(i.quantity)} ${escapeHtml(i.unit||"unit")} · ${money(i.unitPrice||0)} / ${escapeHtml(i.unit||"unit")}</span></div>`).join("")||'<div class="empty-state">No line items recorded.</div>'}</div>
  <div class="po-action-grid"><section><h5>Acknowledge</h5><form id="supplierPOAckForm" class="finance-form"><select name="response"><option value="accepted">Accept purchase order</option><option value="changes_requested">Request changes</option><option value="rejected">Reject purchase order</option></select><textarea name="note" rows="2" placeholder="Optional note"></textarea><button class="btn btn-primary">Send response</button></form>${ack?`<p class="muted">Latest response: <strong>${escapeHtml(ack.response)}</strong>${ack.note?` — ${escapeHtml(ack.note)}`:""}</p>`:""}</section>
  <section><h5>Delivery confirmation</h5><form id="supplierPODeliveryForm" class="finance-form"><input name="expectedDeliveryDate" type="date" value="${escapeAttr(po.supplierExpectedDeliveryDate||po.expectedDeliveryDate||"")}" required><textarea name="note" rows="2" placeholder="Delivery timing or fulfilment note"></textarea><button class="btn btn-primary">Confirm expected delivery</button></form>${conf?`<p class="muted">Latest supplier confirmation: <strong>${escapeHtml(conf.expectedDeliveryDate)}</strong></p>`:""}</section>
  <section><h5>Report an exception</h5><form id="supplierPOExceptionForm" class="finance-form"><select name="type"><option value="quantity_shortage">Quantity shortage</option><option value="price_issue">Price issue</option><option value="delivery_delay">Delivery delay</option><option value="stock_issue">Stock issue</option><option value="document_issue">Document issue</option><option value="other">Other</option></select><textarea name="message" rows="3" required placeholder="Explain the issue clearly"></textarea><button class="btn btn-ghost">Report exception</button></form></section>
  <section><h5>Message BUILDIVA</h5><form id="supplierPOMessageForm" class="finance-form"><textarea name="message" rows="3" required placeholder="Message for the BUILDIVA purchasing team"></textarea><button class="btn btn-ghost">Send message</button></form></section></div>
  <div class="po-history"><h5>Collaboration history</h5>${[...(c.exceptions||[]).map(x=>({date:x.createdAt,type:`Exception · ${x.type}`,text:x.message,status:x.status})),...(c.messages||[]).map(x=>({date:x.createdAt,type:"Message",text:x.message})),...(c.acknowledgements||[]).map(x=>({date:x.createdAt,type:"Supplier response",text:`${x.response}${x.note?` — ${x.note}`:""}`})),...(c.deliveryConfirmations||[]).map(x=>({date:x.createdAt,type:"Delivery confirmation",text:x.expectedDeliveryDate+(x.note?` — ${x.note}`:" ")}))].map(x=>`<div class="po-history-row"><strong>${escapeHtml(x.type)}</strong><span>${escapeHtml(x.text)}</span></div>`).join("")||'<div class="empty-state">No collaboration events yet.</div>'}</div>`;
  detail.querySelector('#supplierPOAckForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{await acknowledgePurchaseOrder({purchaseOrderId:id,response:fd.get('response'),note:fd.get('note')});showToast('Purchase order response sent.');renderSupplierPurchaseOrders();}catch(err){showToast(humanAuthError(err))}};
  detail.querySelector('#supplierPODeliveryForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{await confirmPurchaseOrderDelivery({purchaseOrderId:id,expectedDeliveryDate:fd.get('expectedDeliveryDate'),note:fd.get('note')});showToast('Expected delivery date sent.');openSupplierPurchaseOrder(id,orders);}catch(err){showToast(humanAuthError(err))}};
  detail.querySelector('#supplierPOExceptionForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{await submitPurchaseOrderException({purchaseOrderId:id,type:fd.get('type'),message:fd.get('message')});showToast('Exception reported to BUILDIVA.');openSupplierPurchaseOrder(id,orders);}catch(err){showToast(humanAuthError(err))}};
  detail.querySelector('#supplierPOMessageForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{await addPurchaseOrderCollaborationMessage({purchaseOrderId:id,message:fd.get('message')});showToast('Message sent to BUILDIVA.');openSupplierPurchaseOrder(id,orders);}catch(err){showToast(humanAuthError(err))}};
 }catch(e){detail.innerHTML=`<div class="account-error">${escapeHtml(humanAuthError(e))}</div>`}
}

async function renderSupplierIntelligence(uid){
 const panel=document.getElementById("supplierIntelPanel"); if(!panel)return;
 const draw=(d)=>{const m=d.metrics||{};panel.innerHTML=`<div class="intelligence-grid supplier-intel-grid"><div><span>Overall score</span><strong>${Number(m.overallScore||0)}/100</strong></div><div><span>Reliability</span><strong>${Number(m.reliability||0)}/100</strong></div><div><span>Responsiveness</span><strong>${Number(m.responsiveness||0)}/100</strong></div><div><span>Verification</span><strong>${Number(m.verificationStrength||0)}/100</strong></div><div><span>Published products</span><strong>${Number(m.publishedProducts||0)}</strong></div><div><span>Completed orders</span><strong>${Number(m.completedOrders||0)}</strong></div></div><div class="supplier-risk-list"><strong>Risk flags</strong><p class="muted">${(d.riskFlags||[]).length?(d.riskFlags||[]).map(x=>escapeHtml(x.replace(/_/g," "))).join(" · "):"No current risk flags detected from recorded data."}</p></div>`};
 try{draw(await getSupplierIntelligence(uid));document.getElementById("refreshSupplierIntel")?.addEventListener("click",async()=>{try{panel.innerHTML='<div class="account-loading">Recalculating…</div>';draw(await recalculateSupplierIntelligence(uid));}catch(e){showToast(humanAuthError(e))}})}catch(e){panel.innerHTML=`<div class="account-error">${escapeHtml(humanAuthError(e))}</div>`}
}

