 box.querySelector('#marketingTemplateForm').onsubmit=async e=>{e.preventDefault();try{await createCommunicationTemplate(Object.fromEntries(new FormData(e.currentTarget).entries()));e.currentTarget.reset();showToast('Template saved.');render()}catch(err){showToast(humanAuthError(err))}};
 box.querySelector('#marketingEngagementForm').onsubmit=async e=>{e.preventDefault();try{await logCampaignEngagement(Object.fromEntries(new FormData(e.currentTarget).entries()));e.currentTarget.reset();showToast('Engagement event recorded.');render()}catch(err){showToast(humanAuthError(err))}};
 box.querySelector('#marketingFollowupForm').onsubmit=async e=>{e.preventDefault();try{await createMarketingFollowUp(Object.fromEntries(new FormData(e.currentTarget).entries()));e.currentTarget.reset();showToast('Follow-up created.');render()}catch(err){showToast(humanAuthError(err))}};
