async function renderSupportAdmin(panel){
 const box=document.createElement("section");box.className="account-card admin-centre support-centre";box.innerHTML=`<div class="section-mini-head"><div><p class="eyebrow">STAGE 19 · CUSTOMER SUPPORT</p><h3>Helpdesk & Service Management</h3><p class="muted">Manage customer support tickets, SLA priorities, assignments, internal notes and service history. No support performance is fabricated.</p></div></div><div id="supportMetrics" class="admin-metrics"><div class="account-loading">Loading support…</div></div><div class="support-grid"><section><h4>Ticket queue</h4><div id="supportTickets" class="admin-list">Loading…</div></section><section><h4>New ticket</h4><form id="supportTicketForm" class="finance-form"><input name="subject" placeholder="Customer issue / request" required><select name="category"><option value="order">Order</option><option value="payment">Payment</option><option value="delivery">Delivery</option><option value="supplier">Supplier</option><option value="account">Account</option><option value="procurement">Procurement</option><option value="technical">Technical</option><option value="billing">Billing</option><option value="general">General</option></select><select name="priority"><option value="normal">Normal</option><option value="low">Low</option><option value="high">High</option><option value="urgent">Urgent</option></select><input name="requesterId" placeholder="Customer user ID" required><textarea name="description" rows="5" placeholder="Describe the customer's issue" required></textarea><input name="orderId" placeholder="Order ID (optional)"><button class="btn btn-primary">Create support ticket</button></form></section></div><section class="support-detail"><h4>Selected ticket</h4><div id="supportSelected" class="empty-state">Select a ticket to view details and respond.</div></section>`;panel.appendChild(box);
 let selected=null;
 const render=async()=>{try{const d=await getSupportOverview(),m=d.metrics||{};box.querySelector('#supportMetrics').innerHTML=[["Tickets",m.tickets],["Open",m.openTickets],["Urgent",m.urgentTickets],["SLA overdue",m.overdueSla],["Resolved",m.resolved],["Closed",m.closed],["Messages",m.messages]].map(x=>`<div class="admin-metric"><span>${escapeHtml(x[0])}</span><strong>${escapeHtml(String(x[1]??0))}</strong></div>`).join('');box.querySelector('#supportTickets').innerHTML=(d.tickets||[]).slice(0,80).map(t=>`<div class="admin-row support-ticket-row"><div><strong>${escapeHtml(t.ticketNumber||t.id.slice(0,8).toUpperCase())}</strong><span>${escapeHtml(t.subject)} · ${escapeHtml(t.priority)} · ${escapeHtml(String(t.status).replace(/_/g,' '))}</span></div><div class="admin-actions"><span class="status-pill ${escapeAttr(t.status)}">${escapeHtml(String(t.status).replace(/_/g,' '))}</span><button class="btn btn-ghost" data-support-open="${escapeAttr(t.id)}">Open</button></div></div>`).join('')||`<div class="empty-state">No support tickets yet.</div>`;box.querySelectorAll('[data-support-open]').forEach(b=>b.onclick=()=>openTicket(b.dataset.supportOpen,d.tickets||[]));}catch(e){box.querySelector('#supportMetrics').innerHTML=`<div class="account-error">${escapeHtml(humanAuthError(e))}</div>`}};
 async function openTicket(id,tickets){selected=tickets.find(t=>t.id===id);if(!selected)return;const panel=box.querySelector('#supportSelected');panel.innerHTML=`<div class="support-ticket-header"><div><span class="status-pill ${escapeAttr(selected.status)}">${escapeHtml(String(selected.status).replace(/_/g,' '))}</span><h4>${escapeHtml(selected.ticketNumber||selected.id)}</h4><p>${escapeHtml(selected.subject)}</p></div><div><strong>${escapeHtml(selected.priority)}</strong><small>SLA: ${escapeHtml(fmtDate(selected.slaDueAt)||'Not set')}</small></div></div><p class="muted">${escapeHtml(selected.description||'')}</p><div class="readiness-grid"><label>Status<select id="supportStatus"><option value="open">Open</option><option value="in_progress">In progress</option><option value="waiting_customer">Waiting customer</option><option value="waiting_internal">Waiting internal</option><option value="resolved">Resolved</option><option value="closed">Closed</option><option value="cancelled">Cancelled</option></select></label><label>Priority<select id="supportPriority"><option value="low">Low</option><option value="normal">Normal</option><option value="high">High</option><option value="urgent">Urgent</option></select></label><label>Assigned admin<input id="supportAssignee" value="${escapeAttr(selected.assignedTo||'')}"></label></div><div class="support-actions"><button class="btn btn-primary" id="supportSave">Save ticket</button></div><form id="supportReply" class="finance-form"><textarea name="body" rows="4" placeholder="Reply to customer or add internal note" required></textarea><label class="check-row"><input type="checkbox" name="internal"> Internal note only</label><button class="btn btn-ghost">Add message</button></form>`;panel.querySelector('#supportStatus').value=selected.status;panel.querySelector('#supportPriority').value=selected.priority;panel.querySelector('#supportSave').onclick=async()=>{try{await updateSupportTicket({ticketId:id,status:panel.querySelector('#supportStatus').value,priority:panel.querySelector('#supportPriority').value,assignedTo:panel.querySelector('#supportAssignee').value});showToast('Support ticket updated.');await render();openTicket(id,(await getSupportOverview()).tickets||[])}catch(e){showToast(humanAuthError(e))}};panel.querySelector('#supportReply').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{await addSupportMessage({ticketId:id,body:fd.get('body'),internal:fd.get('internal')==='on'});e.currentTarget.reset();showToast('Support message added.');await render();openTicket(id,(await getSupportOverview()).tickets||[])}catch(err){showToast(humanAuthError(err))}};}
 box.querySelector('#supportTicketForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{const data=Object.fromEntries(fd.entries());data.channel='system';await createSupportTicket(data);e.currentTarget.reset();showToast('Support ticket created.');render()}catch(err){showToast(humanAuthError(err))}};await render();
}

