async function renderOrdersPanel(userId){
 const panel=document.getElementById("ordersPanel"); if(!panel||!userId)return;
 panel.innerHTML=`<div class="account-loading">Loading orders and invoices…</div>`;
 try{
  const [orders,invoices]=await Promise.all([getCustomerOrders(userId),getCustomerInvoices(userId)]);
  if(!orders.length){panel.innerHTML=`<div class="account-card orders-card"><div class="section-mini-head"><div><p class="eyebrow">ORDERS & CHECKOUT</p><h3>My orders</h3></div><span class="status-pill">No orders</span></div><p class="muted">When you select a supplier quotation, your order will appear here for confirmation, invoicing and payment.</p></div>`;return;}
  panel.innerHTML=`<div class="account-card orders-card"><div class="section-mini-head"><div><p class="eyebrow">ORDERS & CHECKOUT</p><h3>My orders</h3></div><span class="muted">${orders.length} order${orders.length===1?'':'s'}</span></div><div class="order-list">${orders.map(o=>orderCard(o,invoices)).join('')}</div></div>`;
  panel.querySelectorAll('[data-checkout-order]').forEach(b=>b.onclick=()=>openCheckoutModal(orders.find(o=>o.id===b.dataset.checkoutOrder)));
  panel.querySelectorAll('[data-cancel-order]').forEach(b=>b.onclick=async()=>{if(!confirm('Cancel this order?'))return;try{await cancelOrder(b.dataset.cancelOrder);showToast('Order cancelled.');renderOrdersPanel(userId);}catch(e){showToast(humanAuthError(e))}});
  await renderCustomerDeliveries(userId,panel);
 }catch(e){panel.innerHTML=`<div class="account-card orders-card"><h3>Orders unavailable</h3><p class="muted">${escapeHtml(humanAuthError(e))}</p></div>`;}
}
async function renderCustomerDeliveries(userId,panel){
 try{const deliveries=await getCustomerDeliveries(userId); const box=document.createElement("section"); box.className="account-card delivery-tracking-card"; box.innerHTML=`<div class="section-mini-head"><div><p class="eyebrow">LOGISTICS</p><h3>Delivery tracking</h3><p class="muted">Track fulfilment milestones recorded by BUILDIVA and its approved fulfilment workflow.</p></div><span class="status-pill">${deliveries.length} delivery${deliveries.length===1?"":"ies"}</span></div>${deliveries.length?`<div class="delivery-list">${deliveries.map(d=>deliveryCard(d)).join("")}</div>`:`<div class="empty-state">Delivery tracking will appear after an order enters fulfilment.</div>`}`; panel.appendChild(box); box.querySelectorAll('[data-delivery-status]').forEach(()=>{}); }catch(e){}
}
function deliveryCard(d){const steps=["pending","assigned","picked_up","in_transit","out_for_delivery","delivered"];const current=steps.indexOf(d.status);return `<article class="delivery-card"><div class="delivery-head"><div><strong>${escapeHtml(d.trackingReference||"Delivery "+d.id.slice(0,8).toUpperCase())}</strong><span>${escapeHtml(orderStatusLabel(d.status||"pending"))}</span></div><span>${escapeHtml(d.deliveryAddress?.city||d.deliveryAddress?.state||"Delivery address")}</span></div><div class="delivery-steps">${steps.map((x,i)=>`<span class="${i<=current?"done":""}">${escapeHtml(orderStatusLabel(x))}</span>`).join("")}</div>${d.proofOfDelivery?.url?`<a class="btn btn-ghost" href="${escapeAttr(d.proofOfDelivery.url)}" target="_blank" rel="noopener">View proof of delivery</a>`:""}</article>`}

function orderStatusLabel(s){return String(s||'').replaceAll('_',' ')}
function money(n){return `₦${Number(n||0).toLocaleString('en-NG',{minimumFractionDigits:2,maximumFractionDigits:2})}`}
function orderCard(o,invoices){
 const inv=invoices.find(i=>i.id===o.invoiceId||i.orderId===o.id);
 const canCheckout=o.status==='awaiting_confirmation'&&o.paymentStatus==='unpaid';
 const canCancel=['awaiting_confirmation','awaiting_payment'].includes(o.status);
 return `<article class="order-card"><div class="order-head"><div><strong>Order ${escapeHtml(o.id.slice(0,8).toUpperCase())}</strong><span>${escapeHtml(orderStatusLabel(o.status))}</span></div><div class="order-total">${money(o.total)}</div></div><div class="order-summary"><span>${(o.items||[]).length} item line${(o.items||[]).length===1?'':'s'}</span><span>Payment: ${escapeHtml(orderStatusLabel(o.paymentStatus||'unpaid'))}</span>${inv?`<span>Invoice: ${escapeHtml(inv.invoiceNumber||inv.id.slice(0,8))}</span>`:''}</div><div class="order-items">${(o.items||[]).map(i=>`<span>${escapeHtml(i.name||'Item')} × ${escapeHtml(i.quantity)} ${escapeHtml(i.unit||'unit')}</span>`).join('')}</div><div class="order-delivery-mini"><strong>Fulfilment:</strong> ${escapeHtml(orderStatusLabel(o.deliveryStatus||"pending"))}</div>${canCheckout?`<div class="order-actions"><button class="btn btn-primary" data-checkout-order="${escapeAttr(o.id)}">Confirm & checkout</button></div>`:''}${canCancel?`<div class="order-actions"><button class="btn btn-ghost" data-cancel-order="${escapeAttr(o.id)}">Cancel order</button></div>`:''}</article>`;
}
async function openCheckoutModal(order){
 if(!order)return;
 let modal=document.getElementById('checkoutModal');
 if(!modal){modal=document.createElement('div');modal.id='checkoutModal';modal.className='modal-backdrop';modal.hidden=true;modal.innerHTML=`<div class="account-modal checkout-modal" role="dialog" aria-modal="true"><button class="modal-close" id="closeCheckout" aria-label="Close">×</button><div id="checkoutPanel"></div></div>`;document.body.appendChild(modal);document.getElementById('closeCheckout').onclick=()=>modal.hidden=true;modal.addEventListener('click',e=>{if(e.target===modal)modal.hidden=true});}
 const panel=document.getElementById('checkoutPanel');
 let addresses=[]; try{addresses=await getAddresses(auth.currentUser.uid)}catch{}
 const addressOptions=addresses.map(a=>`<option value="${escapeAttr(a.id)}">${escapeHtml(a.label||'Address')} — ${escapeHtml(a.city||'')}, ${escapeHtml(a.state||'')}</option>`).join('');
 panel.innerHTML=`<p class="eyebrow">CHECKOUT</p><h2>Confirm your BUILDIVA order</h2><p class="muted">Review the order total before choosing how you want to pay. Online card/mobile-money processing will be connected only after a verified payment provider is configured.</p><div class="checkout-total"><span>Total</span><strong>${money(order.total)}</strong></div><label class="checkout-address">Delivery address<select id="checkoutAddress" ${addresses.length?"":"disabled"}>${addressOptions||'<option>No saved address — add one in your account first</option>'}</select></label><div class="payment-options"><label class="payment-option"><input type="radio" name="paymentMethod" value="bank_transfer" checked><span><strong>Bank transfer</strong><small>Receive an invoice/payment reference. Payment remains pending until verified.</small></span></label><label class="payment-option"><input type="radio" name="paymentMethod" value="pay_on_delivery"><span><strong>Pay on delivery</strong><small>Confirm the order now and settle according to the agreed delivery terms.</small></span></label></div><p class="form-message" id="checkoutMessage"></p><button class="btn btn-primary full" id="confirmCheckoutBtn">Confirm order</button>`;
 panel.querySelector('#confirmCheckoutBtn').onclick=async()=>{const method=panel.querySelector('input[name=paymentMethod]:checked')?.value;const msg=panel.querySelector('#checkoutMessage');msg.textContent='Creating invoice and checkout record…';try{const selectedAddress=addresses.find(a=>a.id===panel.querySelector('#checkoutAddress')?.value); if(!selectedAddress){msg.textContent='Please add and select a delivery address in your account before confirming the order.';return;} const result=await confirmOrderAndCreateInvoice({orderId:order.id,paymentMethod:method,deliveryAddress:selectedAddress});modal.hidden=true;showToast(`Order confirmed. Invoice ${result.invoiceNumber} created.`);renderOrdersPanel(auth.currentUser.uid);}catch(e){msg.textContent=humanAuthError(e)}};
 modal.hidden=false;
}


