 box.innerHTML=`<div class="section-mini-head"><div><p class="eyebrow">STAGE 20 · INVENTORY & WAREHOUSE</p><h3>Inventory command centre</h3><p class="muted">Track verified stock across BUILDIVA warehouses. Stock values are operational records, not proof of physical inventory.</p></div><button class="btn btn-ghost" id="refreshInventory">Refresh</button></div><div id="inventoryMetrics" class="admin-metrics">Loading…</div><div class="admin-grid"><section><h4>Low-stock items</h4><div id="lowStockItems" class="admin-list">Loading…</div></section><section><h4>Recent stock movements</h4><div id="inventoryTransactions" class="admin-list">Loading…</div></section></div><div class="admin-grid" style="margin-top:18px"><section><h4>Add warehouse</h4><form id="warehouseForm" class="stack-form"><input name="name" placeholder="Warehouse name" required><input name="code" placeholder="Code"><input name="city" placeholder="City"><input name="state" placeholder="State"><input name="address" placeholder="Address"><input name="capacity" type="number" min="0" placeholder="Capacity (optional)"><button class="btn btn-primary">Create warehouse</button></form></section><section><h4>Add inventory item</h4><form id="inventoryForm" class="stack-form"><input name="productId" placeholder="Product ID (optional)"><input name="productName" placeholder="Product name" required><input name="sku" placeholder="SKU"><input name="category" placeholder="Category"><input name="unit" placeholder="Unit (e.g. bag)" value="unit"><select name="warehouseId" id="inventoryWarehouse" required><option value="">Loading warehouses…</option></select><input name="onHand" type="number" min="0" step="any" placeholder="Opening stock" value="0"><input name="reorderLevel" type="number" min="0" step="any" placeholder="Reorder level" value="0"><input name="unitCost" type="number" min="0" step="any" placeholder="Unit cost (NGN)" value="0"><button class="btn btn-primary">Create stock record</button></form></section></div>`;
