  box.querySelector('#accessLimits').innerHTML=lims.filter(x=>x.active!==false).map(x=>`<div class="admin-row"><div><strong>${esc(x.roleKey)}</strong><span>${esc(x.scope)} · ${esc(x.currency||'NGN')} ${Number(x.amount||0).toLocaleString()}</span><small>${x.requiresSecondApproval?'Second approval required':'Single-role limit'}</small></div></div>`).join('')||'<div class="empty-state">No approval limits.</div>';
