async function renderStage32Approvals(panel){
 const box=document.createElement("section");box.className="admin-section stage32-approvals";box.innerHTML=`<div class="section-heading"><div><span class="eyebrow">STAGE 32</span><h3>Approval & Workflow Centre</h3><p>Multi-level approvals with segregation of duties and an auditable decision trail.</p></div><button id="approvalRefresh" class="btn btn-ghost">Refresh</button></div>
 <div id="approvalMetrics" class="report-grid"></div>
 <div class="report-grid"><section><h4>Create approval request</h4><form id="approvalCreateForm" class="stack-form"><input name="title" placeholder="Approval title" required><input name="requestType" placeholder="Request type (purchase, expense, bid...)" value="general"><input name="sourceCollection" placeholder="Source collection (optional)"><input name="sourceId" placeholder="Source record ID (optional)"><input name="amount" type="number" min="0" step="0.01" placeholder="Amount"><input name="currency" value="NGN" maxlength="10"><textarea name="description" placeholder="Description"></textarea><textarea name="steps" placeholder='Steps JSON, e.g. [{"roleKey":"finance_manager"},{"roleKey":"super_admin"}]' required></textarea><button class="btn btn-primary">Create workflow</button><div class="form-message"></div></form></section><section><h4>Recent pending workflows</h4><div id="approvalList" class="document-list"></div></section></div>`;panel.appendChild(box);
 const esc=v=>escapeHtml(v==null?"":String(v));
 const render=async()=>{try{const [d,requests]=await Promise.all([getApprovalDashboard(),getApprovalRequests({})]);const c=d.counts||{};box.querySelector('#approvalMetrics').innerHTML=[['Pending',c.pending||0],['Approved',c.approved||0],['Rejected',c.rejected||0],['Cancelled',c.cancelled||0]].map(x=>`<div class="admin-metric"><span>${esc(x[0])}</span><strong>${esc(x[1])}</strong></div>`).join('');const rows=requests.requests||[];box.querySelector('#approvalList').innerHTML=rows.slice(0,50).map(r=>{const step=r.steps?.[(r.currentStep||1)-1]||{};return `<div class="admin-row"><div><strong>${esc(r.title)}</strong><span>${esc(r.requestType||'general')} · ${esc(r.currency||'NGN')} ${Number(r.amount||0).toLocaleString()} · step ${esc(r.currentStep||1)}/${esc(r.steps?.length||0)}</span><small>${esc(r.status)} · approver ${esc(step.approverUid||step.roleKey||'unassigned')}</small></div><div class="admin-actions">${r.canApprove?`<button class="btn btn-primary" data-approve="${escapeAttr(r.id)}">Approve</button><button class="btn btn-ghost" data-reject="${escapeAttr(r.id)}">Reject</button>`:''}${r.status==='pending'&&r.requestedBy===auth.currentUser?.uid?`<button class="btn btn-ghost" data-cancel="${escapeAttr(r.id)}">Cancel</button>`:''}</div></div>`}).join('')||'<div class="empty-state">No workflows visible to this account.</div>';
 box.querySelectorAll('[data-approve]').forEach(b=>b.onclick=async()=>{try{await approveApprovalRequest({id:b.dataset.approve,comment:'Approved in BUILDIVA Approval Centre'});showToast('Approval recorded.');await render()}catch(e){showToast(humanAuthError(e))}});
 box.querySelectorAll('[data-reject]').forEach(b=>b.onclick=async()=>{const comment=prompt('Reason for rejection:');if(!comment)return;try{await rejectApprovalRequest({id:b.dataset.reject,comment});showToast('Rejection recorded.');await render()}catch(e){showToast(humanAuthError(e))}});
 box.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=async()=>{if(!confirm('Cancel this workflow?'))return;try{await cancelApprovalRequest({id:b.dataset.cancel,reason:'Cancelled by requester'});showToast('Workflow cancelled.');await render()}catch(e){showToast(humanAuthError(e))}});
 }catch(e){box.querySelector('#approvalMetrics').innerHTML=`<div class="account-error">${esc(humanAuthError(e))}</div>`}}
 box.querySelector('#approvalRefresh').onclick=render;
 box.querySelector('#approvalCreateForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,d=Object.fromEntries(new FormData(f).entries());try{d.amount=Number(d.amount||0);d.steps=JSON.parse(d.steps);await createApprovalRequest(d);f.querySelector('.form-message').textContent='Approval workflow created.';f.reset();f.querySelector('[name="currency"]').value='NGN';await render()}catch(err){f.querySelector('.form-message').textContent=humanAuthError(err)}};
 await render();
}


