 document.getElementById("s34QueueForm").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),m=document.getElementById('s34QueueMsg');try{await enqueueStage34Communication({userId:f.get('userId'),channel:f.get('channel'),eventType:f.get('eventType'),subject:f.get('subject'),body:f.get('body')});m.textContent='Message queued.';e.currentTarget.reset();await refresh();}catch(err){m.textContent=humanAuthError(err);}};
 document.getElementById("s34Prefs").onclick=async()=>{try{const p=await getStage34NotificationPreferences();const r=confirm(`Notification preferences\n\nIn-app: ${p.inApp?'ON':'OFF'}\nEmail: ${p.email?'ON':'OFF'}\nSMS: ${p.sms?'ON':'OFF'}\nWhatsApp: ${p.whatsapp?'ON':'OFF'}\n\nPress OK to enable email and in-app, or Cancel to leave unchanged.`);if(r){await saveStage34NotificationPreferences({...p,inApp:true,email:true});showToast('Notification preferences saved.');}}catch(e){showToast(humanAuthError(e));}};
