 box.innerHTML=`<div class="section-heading"><div><p class="eyebrow">STAGE 35</p><h2>Enterprise API & Integration Gateway</h2><p class="muted">Manage provider connections, webhook intake, outbound jobs and integration health without exposing credentials in the browser.</p></div><div class="button-row"><button class="btn btn-ghost" id="s35Refresh">Refresh</button><button class="btn btn-primary" id="s35Run">Run integration queue</button></div></div><div class="stats-grid" id="s35Stats"></div><div class="stage35-grid"><div class="panel-card"><h3>Register integration</h3><form id="s35IntegrationForm"><input name="key" required placeholder="Integration key e.g. payment_provider"><input name="name" required placeholder="Display name"><select name="type"><option value="payment">Payment provider</option><option value="bank">Bank / finance</option><option value="government">Government system</option><option value="logistics">Logistics provider</option><option value="supplier">Supplier system</option><option value="communication">Communication provider</option><option value="custom">Custom API</option></select><input name="baseUrl" placeholder="HTTPS API base URL (optional)"><input name="secretEnv" placeholder="Secret environment variable name (optional)"><select name="active"><option value="true">Active</option><option value="false">Disabled</option></select><button class="btn btn-primary" type="submit">Create integration</button><p class="form-message" id="s35CreateMsg"></p></form></div><div class="panel-card"><h3>Queue API operation</h3><form id="s35JobForm"><input name="integrationKey" required placeholder="Integration key"><input name="operation" required placeholder="Operation e.g. create_payment"><select name="method"><option>POST</option><option>GET</option><option>PUT</option><option>PATCH</option></select><input name="path" required placeholder="/v1/resource"><textarea name="payload" rows="5" placeholder='{"reference":"...","amount":0}'></textarea><button class="btn btn-primary" type="submit">Queue operation</button><p class="form-message" id="s35JobMsg"></p></form></div></div><div class="panel-card"><h3>Integration registry</h3><div id="s35Integrations" class="table-list"></div></div><div class="panel-card"><h3>Recent gateway activity</h3><div id="s35Logs" class="table-list"></div></div>`;
